export type BenchmarkRow = {
  model: string; provider: string;
  overall: number; format: number; voice: number; low: number; high: number;
  words: number; emDashes: number; contrast: number; faq: number; cta: number;
  cost: number; seconds: number;
  keyword: number; metaTitle: number; metaDesc: number;
  wordsOff: number; inRange: number; longParas: number; openers: number; aiWords: number;
};

export type CopyRow = {
  model: string; provider: string;
  overall: number; code: number; judge: number;
  clarity: number; persuasion: number; voice: number; specificity: number;
  limits: number; // hard limits met, of 60 (20 per pack)
  adLimits: number; // Google Ads headline/description length limits met, of 15
  facts: number; // brief facts used, of 12
  aiWords: number; emDashes: number; cost: number;
};

/** SEO checks passed, of 18: keyword placement (9), meta title (3), meta description (3), FAQ (3). */
export const seoScore = (r: BenchmarkRow) => r.keyword + r.metaTitle + r.metaDesc + r.faq;

